/*
 * Firmware symbols an Axon model image may bind to, shared by all model slots. Built once per
 * firmware by model_ota_axon_add_binding_table(). Each row is a struct model_image_binding_entry.
 */

/* Binding symbols and their name hashes, generated by axon_elf.py binding-table. */
#include "model_ota_axon_binding_table.h"

#ifndef MODEL_OTA_AXON_BINDING_SYMBOL_COUNT
#error "MODEL_OTA_AXON_BINDING_SYMBOL_COUNT must be defined"
#endif

.syntax unified
.section .rodata.model_ota_axon_binding_table,"a",%progbits
.balign 4

.global model_ota_axon_binding_table
.type model_ota_axon_binding_table, %object
model_ota_axon_binding_table:
#define MODEL_OTA_AXON_BINDING_ENTRY(symbol)                                                       \
	.word MODEL_OTA_AXON_SYM_HASH(symbol);                                                     \
	.word symbol;
MODEL_OTA_AXON_BINDING_REFS(MODEL_OTA_AXON_BINDING_ENTRY)
.size model_ota_axon_binding_table, . - model_ota_axon_binding_table

.global model_ota_axon_binding_count
.type model_ota_axon_binding_count, %object
model_ota_axon_binding_count:
	.word MODEL_OTA_AXON_BINDING_SYMBOL_COUNT
.size model_ota_axon_binding_count, . - model_ota_axon_binding_count
